export const getGetAdminUserMessagesUrl = (id: string,
    params?: GetAdminUserMessagesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/admin/users/${id}/messages?${stringifiedParams}` : `/api/admin/users/${id}/messages`
}

